import {katrinaTrack,atlanticSeasons,windBands} from './cyclone-data.js?v=20261023-weather03';
import {worldPath,gulfPath} from './cyclone-map.js?v=20261023-weather03';
export const weatherViews3={
 'weather-cyclone-form':[['ingredients','Warm ocean & conditions'],['cycle','Developing circulation'],['section','Eye & eyewall'],['shear','Disrupting wind shear']],
 'weather-cyclone-patterns':[['basins','Global source areas'],['track26','26 August 00UTC'],['track28','28 August 18UTC'],['track29','29 August 12UTC'],['seasons','Compare seasons'],['change','Change & uncertainty']],
 'weather-katrina':[['surge','Surge & flooding'],['scale','Wind classification'],['impacts','Dated impact evidence'],['links','Connected impacts']],
 'weather-haiyan':[['satellite','NASA satellite image'],['surge','Coastal hazard process'],['livelihoods','Livelihood recovery'],['evidence','Dated impact evidence']],
 'weather-cyclone-response':[['usa','USA response network'],['philippines','Philippines network'],['compare','Compare access'],['hazards','Compound hazards']]
};
export const weatherRequirements3=Object.fromEntries(Object.entries(weatherViews3).map(([k,v])=>[k,v.map(x=>x[0])]));
export const weatherAnimated3=(k,v)=>k==='weather-cyclone-form'||k==='weather-katrina'&&v==='surge'||k==='weather-haiyan'&&['surge','livelihoods'].includes(v)||k==='weather-cyclone-response'&&['usa','philippines','hazards'].includes(v);
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b7d5df',w=3,extra='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" ${extra}/>`;
const ar=(x,y,a,b,c='#efb29a')=>path(`M${x} ${y}L${a} ${b}`,c,3,'marker-end="url(#w3Arrow)"');
const dot=(x,y,r=6,c='#f3bea6')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,label)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="#385569" stroke="#a4c0ca"/>`+tx(x+10,y+26,label,12);
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="w3Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#efb29a"/></marker><clipPath id="w3GulfClip"><rect x="45" y="75" width="370" height="210"/></clipPath></defs><g fill="#eef2f3" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`;
const nhc='https://www.nhc.noaa.gov/data/tcr/AL122005_Katrina.pdf';
const fao='https://www.fao.org/fileadmin/user_upload/emergencies/docs/FAO%20Typhoon%20Haiyan%20Executive%20Brief%2030%20April%202014.pdf';
const table=(caption,heads,rows)=>`<table class="geo-data"><caption>${caption}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${row[0]}</th>${row.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
export function haiyanSatellite(teaching=false){return `<figure style="margin:0"><img src="./geography/images/haiyan-modis-2013-11-07.jpg" width="720" height="540" style="width:100%;height:auto;border-radius:12px" alt="NASA natural-colour satellite image dated7November2013. Spiral cloud bands surround a small eye east of the labelled Philippines; Palau lies southeast. North arrow and100km scale appear in the original image."><figcaption class="geo-caption">Aqua/MODIS ·7November2013 · ${link('https://science.nasa.gov/earth/earth-observatory/super-typhoon-haiyan-82341/','NASA LANCE/EOSDIS MODIS Rapid Response Team, GSFC')} · image unchanged · ${link('https://www.nasa.gov/nasa-brand-center/images-and-media/','NASA educational media terms')}.${teaching?' Before landfall; the cloud image does not measure casualties or ground damage.':''}</figcaption></figure>`;}
export function cycloneEvidence(view){
 if(view==='satellite')return haiyanSatellite(false);
 if(view==='scale')return table('Saffir–Simpson hurricane wind scale · maximum sustained1-minute wind · knots (kt)',['Category','Wind kt'],windBands.map(b=>[b.category,b.max===null?b.min+'+':b.min+'–'+b.max]))+`<p class="geo-caption">${link('https://www.nhc.noaa.gov/aboutsshws.php','NHC wind scale')} · units:knots (kt) · checked23October2026.</p>`;
 if(view==='seasons')return table('Atlantic seasons · reported counts · NOAA season summaries',['Year','Named storms','Hurricanes','Major'],atlanticSeasons.map(s=>[s.year,s.named,s.hurricanes,s.major]))+`<p class="geo-caption">${link('https://www.noaa.gov/media-release/record-breaking-atlantic-hurricane-season-draws-to-end','NOAA2020,30November2020')} · ${link('https://www.noaa.gov/news-release/damaging-2022-atlantic-hurricane-season-draws-to-close','NOAA2022,29November2022')}. Hurricanes and major hurricanes are subsets of named storms.</p>`;
 if(view==='haiyan')return table('Philippines: Haiyan · FAO estimates published30April2014',['Indicator','Estimate'],[['Coconut trees damaged / destroyed','33million'],['Fishing boats affected','30,000'],['Of affected boats: lost / destroyed','10,000']])+`<p class="geo-caption">${link(fao,'FAO30April2014 executive brief')}. Rounded estimates and different impact definitions; not a live census.</p>`;
 if(view==='katrina')return table('Katrina · NHC report updated4January2023',['Fatality classification','Number'],[['Direct','520'],['Indirect','565'],['Indeterminate cause','307'],['Combined total','1,392']])+`<p class="geo-caption">${link(nhc,'NHC tropical cyclone report')}. Earlier reported totals differ. Counts refer to the report’s defined cases, not all global cyclones or wind-only deaths.</p>`;
 if(view==='track')return trackMap('track29')+table('Selected Katrina best-track observations · August2005 · UTC',['Date / UTC','Latitude°N','Longitude°W'],[[28,'1800',26.3,88.6],[29,'1200',29.5,89.6]].map(([d,t,a,b])=>[d+' / '+t,a,b]));
 return '';
}
function trackMap(v){const [day,time]=v==='track26'?[26,'0000']:v==='track28'?[28,'1800']:[29,'1200'],p=katrinaTrack.find(p=>p.day===day&&p.time===time),X=lon=>45+(lon+100)/40*370,Y=lat=>285-(lat-15)/25*210;
 let b=tx(20,28,'KATRINA · OBSERVED BEST TRACK',15)+tx(20,52,`${day}August2005 · ${time}UTC · wind${p.wind}kt`,12)+`<rect x="45" y="75" width="370" height="210" fill="#406b82"/><g clip-path="url(#w3GulfClip)"><path d="${gulfPath}" fill="#a0b59f" stroke="#c6d8ce" stroke-width="1"/>`;
 for(let lat=15;lat<=40;lat+=5)b+=path(`M45 ${Y(lat)}H415`,'#c8dbe6',.6,'opacity=".5"');
 for(let lon=-100;lon<=-60;lon+=10)b+=path(`M${X(lon)} 75V285`,'#c8dbe6',.6,'opacity=".5"');
 b+=path(katrinaTrack.map((p,i)=>(i?'L':'M')+X(p.lon).toFixed(2)+' '+Y(p.lat).toFixed(2)).join(' '),'#f5c2aa',2)+dot(X(p.lon),Y(p.lat),7,'#fff0db')+`<circle cx="${X(p.lon)}" cy="${Y(p.lat)}" r="13" fill="none" stroke="#f1aa91" stroke-width="2"/></g>`;
 for(let lat=15;lat<=40;lat+=5)b+=tx(8,Y(lat)+4,lat+'°N',10);
 for(let lon=-100;lon<=-60;lon+=10)b+=tx(X(lon)-15,304,Math.abs(lon)+'°W',10);
 b+=tx(155,110,'USA',12)+tx(110,242,'Mexico',12)+tx(238,235,'Cuba',12)+tx(25,333,`${p.lat}°N · ${Math.abs(p.lon)}°W · ${p.pressure}mb`,13);
 return wrap(b,`Recorded positions23–30August2005; selected${day}August${time}UTC. Equirectangular coordinates, north up. ${link(nhc,'NHC Table1,updated4January2023')} · ${link('./geography/data/katrina-best-track-subset.json','Coordinate source subset')}. Coastlines:Natural Earth public domain, generalised. Connected six-hour positions approximate the path between records, not a forecast or exact continuous movement. Coordinate-track explorer introduces GIS thinking; it is not a full GIS investigation.`);
}
export function weatherScene3(k,selected,t=0){if(!weatherViews3[k])return '';const v=weatherViews3[k].some(x=>x[0]===selected)?selected:weatherViews3[k][0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!weatherAnimated3(k,v))t=0;let b='',c='';
 if(k==='weather-cyclone-form'){
  if(v==='ingredients'){b=tx(24,30,'OCEAN HEAT + SUITABLE ATMOSPHERE',15)+'<rect x="25" y="255" width="390" height="75" rx="14" fill="#679bb1"/>'+tx(40,302,'Warm water through depth · about26.5°C+',13)+ar(100,245,100,115)+dot(100,245-130*t)+ar(140,220,210,150)+tx(190,82,'Moist air',14)+tx(190,116,'Pre-existing disturbance',13)+tx(190,150,'Low vertical wind shear',13)+tx(190,185,'Away from equator',13)+tx(25,52,'Favourable ingredients do not guarantee a storm',11);c='Warm ocean water supplies moisture and energy; low shear, moist air and an existing disturbance help organisation away from the equator. Rising dots trace a conceptual moisture path, not a guaranteed temperature switch or measured evaporation rate.';}
  else if(v==='cycle'){b=tx(24,30,'NORTHERN HEMISPHERE · ANTICLOCKWISE',14);for(let a=0;a<3;a++){const angle=-t*2*Math.PI+a*2*Math.PI/3,r=125-60*t,x=220+Math.cos(angle)*r,y=185+Math.sin(angle)*r;b+=path(`M${220+Math.cos(a*2*Math.PI/3)*125} ${185+Math.sin(a*2*Math.PI/3)*125}Q220 60 220 185`,'#9ebdcb',1)+dot(x,y,7);}b+=dot(220,185,25,'#54768a')+tx(208,190,'LOW',11)+ar(125,125,104,165)+tx(25,310,'Moist ascent → condensation → latent heat release',12)+tx(25,335,'Inflow strengthens; upper outflow removes air aloft',12);c='Symbolic near-surface parcels spiral anticlockwise inward around Northern Hemisphere low pressure. Condensation releases latent heat in rising air; upper-level outflow supports the circulation. Southern Hemisphere surface rotation is clockwise. Timing and parcels are illustrative, not a trajectory forecast.';}
  else if(v==='section'){b=tx(24,30,'MATURE STORM · CROSS SECTION',15)+'<rect x="25" y="275" width="390" height="55" fill="#719caf"/><path d="M50 260Q90 60 160 105L190 260M250 260L280 105Q350 60 395 260" fill="#c5d6dc" opacity=".6"/>'+ar(145,255,145,115)+ar(295,255,295,115)+ar(220,130,220,245)+ar(145,90,55,90)+ar(295,90,390,90)+dot(145,255-140*t,6)+dot(295,255-140*t,6)+dot(220,130+115*t,6,'#b9e0eb')+tx(194,70,'Eye',15)+tx(25,175,'Eyewall',12)+tx(318,175,'Eyewall',12)+tx(25,340,'Rise in eyewall · sink in eye · upper outflow',12);c='A mature cyclone can have strong ascent and winds around the eyewall, descending air in the relatively calm eye and upper outflow. The section is not a scale drawing or wind-speed profile; eye passage does not mean the storm is over.';}
  else{const shift=90*t;b=tx(24,30,'STRONG WIND SHEAR CAN DISRUPT THE CORE',14)+'<rect x="25" y="280" width="390" height="50" fill="#719caf"/>'+path(`M180 270Q${180+shift} 200 ${180+shift} 120`,'#c7dee5',45)+ar(55,90,355,90)+ar(70,255,160,255)+dot(180+shift*t,270-150*t,6)+tx(25,60,'Different winds with height tilt / disrupt organisation',11)+tx(25,340,'Land or cooler water also reduces ocean energy supply',11);c='Vertical wind shear is a change in wind speed or direction with height. Strong shear can disrupt organised convection and weaken a cyclone; cooler water or land can also weaken it. The moving column is a schematic, not a measured shear threshold or a reason to ignore continuing rain hazards.';}
 }
 if(k==='weather-cyclone-patterns'){
  if(v.startsWith('track'))return trackMap(v);
  if(v==='seasons')return cycloneEvidence('seasons');
  if(v==='change'){b=tx(24,30,'COMPARE LIKE RECORDS OVER TIME',15)+box(25,80,390,45,'Frequency ≠ intensity ≠ rainfall')+box(25,145,390,45,'Natural variability + observation coverage')+box(25,210,390,45,'Warming: heavier rain / stronger intensity risk')+tx(25,310,'Not a rule of more storms in every basin every year',12);c='Two Atlantic seasons cannot establish a long-term trend. Detection changes, natural variability and greenhouse warming require separate consideration. Warming supports heavier cyclone rain and higher average intensity, while frequency projections vary. Source:NOAA/GFDL synthesis20November2024; no numerical forecast is generated.';}
  else{b=tx(24,28,'TROPICAL CYCLONE SOURCE AREAS',15);const X=x=>20+(x+180)/360*400,Y=y=>65+(90-y)/180*200;for(const[lo,hi,lat0,lat1]of[[-100,-15,5,30],[-150,-100,5,30],[100,180,5,30],[45,100,5,30],[45,115,-30,-5],[130,180,-30,-5]])b+=`<rect x="${X(lo)}" y="${Y(lat1)}" width="${X(hi)-X(lo)}" height="${Y(lat0)-Y(lat1)}" fill="#f2b69f" opacity=".45"/>`;b+=`<path d="${worldPath}" fill="#9daf9e" stroke="#c4d4cd" stroke-width=".4"/>`+path('M20 165H420','#f0dbb2',1,'stroke-dasharray="5 4"')+tx(25,61,'North',11)+tx(24,183,'Equator',11)+tx(48,277,'Hurricanes: Atlantic / NE Pacific',12)+tx(48,300,'Typhoons: NW Pacific',12)+tx(48,323,'Cyclones: Indian / South Pacific',12);c='Generalised warm-ocean source areas, mostly about5–30°latitude, not hard boundaries or all observed tracks. Natural Earth public-domain equirectangular basemap. Near-equatorial Coriolis is usually too weak; the South Atlantic and southeast Pacific are usually unfavourable, with rare exceptions. Tracks can extend outside formation areas. Sources:NOAA formation basins and structure.';}
 }
 if(k==='weather-katrina'){
  if(v==='scale')return cycloneEvidence('scale');if(v==='impacts')return cycloneEvidence('katrina');
  if(v==='links'){b=tx(24,30,'KATRINA · CONNECTED CONSEQUENCES',15)+box(25,80,390,45,'Flooded homes → displacement / health needs')+box(25,150,390,45,'Damaged businesses / ports → income losses')+box(25,220,390,45,'Debris / contaminants → environmental risks')+tx(25,325,'Wealth does not remove unequal exposure or access',12);c='Social, economic and environmental impacts overlap. Katrina disrupted homes, services and economic infrastructure, while spills/debris affected environments. Not every household had equal transport or protection. Sources:NHC report2023;NOAA response/restoration incident records;USACE history2025.';}
  else return surge('KATRINA · SURGE AND DEFENCE FAILURE',t,'Wind-driven surge and failures of levees/floodwalls contributed to extensive New Orleans flooding. This section illustrates a breach pathway, not the actual geometry, measured surge height, timing or every cause of failure. NHC report2023;USACE history2025.');
 }
 if(k==='weather-haiyan'){
  if(v==='satellite')return haiyanSatellite(true);if(v==='evidence')return cycloneEvidence('haiyan');
  if(v==='surge')return surge('HAIYAN · WIND-DRIVEN COASTAL SURGE',t,'Haiyan storm surge flooded coastal settlements including Tacloban in November2013. Wind pushes seawater landward; local coast shape and depth affect levels. The section is conceptual, not a Tacloban terrain model, measured water depth or a tsunami. Source:UNDRR2023 retrospective.');
  if(v==='livelihoods'){const x=55+300*t;b=tx(24,30,'RESTORING LIVELIHOODS TAKES TIME',15)+path('M55 200H355','#aacbd7',3)+box(25,95,115,55,'Damaged assets')+box(160,95,115,55,'Repair / replant')+box(295,95,120,55,'Income returns')+dot(x,200,8)+tx(25,250,'Boats need gear, skills and safe replacement',12)+tx(25,285,'Coconut trees need years to become productive',12)+tx(25,330,'Compressed causal sequence · not equal recovery times',11);c='FAO30April2014 reported coconut-tree and fishing-boat damage and supported livelihood recovery. Different assets and households recover at different rates; planting does not immediately restore harvests. The resetting dot shows an explanation sequence, not measured progress, an actual aid-delivery timeline or guaranteed recovery.';}
 }
 if(k==='weather-cyclone-response'){
  if(v==='compare'){b=tx(24,30,'COMPARE CAPACITY AND ACCESS',15)+box(25,75,390,48,'Resources + coordination + trusted information')+box(25,150,390,48,'Exposure + transport + health / shelter access')+box(25,225,390,48,'Household and local differences matter')+tx(25,325,'Check dates, definitions and who a source represents',12);c='Both countries relied on multiple actors. USA financial/technical capacity did not eliminate inequality or coordination failures; Philippine communities and institutions had important capabilities. This is an evaluation framework, not a score ranking whole countries or an authentic social-media source.';}
  else if(v==='hazards'){const rain=t*60,slip=t*35;b=tx(24,30,'ONE CYCLONE · SEVERAL HAZARD PATHWAYS',14)+'<path d="M25 275L110 160 200 275Z" fill="#96a79a"/><rect x="220" y="250" width="195" height="70" fill="#6897ad"/>';for(let i=0;i<7;i++)b+=path(`M${35+i*20} ${80+(rain+i*8)%70}l-3 13`,'#b2dce9',2);b+=`<path d="M140 ${200+slip}l30 30-24 12Z" fill="#c6af94"/>`+ar(250,150,390,150)+ar(250,270,405,250)+tx(25,65,'Intense rain → flood / slope instability',11)+tx(230,117,'Damaging winds',12)+tx(230,225,'Surge → coastal flood',12)+tx(25,340,'Rain can trigger landslides on susceptible slopes',12);c='High winds, intense rain, inland flooding, landslides and wind-driven storm surge/coastal flooding are distinct but interacting hazards. This is a general process model, not evidence of a particular landslide in either named case. Slope failure also depends on geology, saturation, vegetation and slope angle.';}
  else{const usa=v==='usa',a=usa?'USA · KATRINA RESPONSE':'PHILIPPINES · HAIYAN RESPONSE';b=tx(24,30,a,15)+box(25,80,180,60,usa?'FEMA / US forces':'National / local agencies')+box(235,80,180,60,usa?'American Red Cross':'Red Cross / UN / NGOs')+box(80,235,280,50,'Households / community networks')+ar(100,155,160,222)+ar(330,155,280,222)+dot(100+60*t,155+67*t,7)+dot(330-50*t,155+67*t,7)+tx(25,190,usa?'Rescue / shelter / food; USACE pumps and repairs':'Relief / shelter / food; FAO livelihoods support',11)+tx(25,330,'Routes and timing symbolic · access and coordination vary',11);c=usa?'Katrina responses included household evacuation, volunteers/Red Cross shelter and food, government/military rescue and USACE unwatering and defence repair. GAO documented coordination and supply problems. Lines show roles, not exact delivery routes or measured response speed.':'Haiyan response combined community action, Philippine government agencies and reconstruction funding with Red Cross, UN and other assistance. FAO supported productive assets and farming recovery. Lines show roles, not precise routes, equal aid access or a claim that outsiders replaced national capacity.';}
 }
 return wrap(b,c);
}
function surge(title,t,c){const level=265-60*t;let b=tx(24,30,title,14)+'<path d="M20 285H240L270 250H420V330H20Z" fill="#91a496"/>'+`<path d="M20 ${level}H265L${275+100*t} 270V330H20Z" fill="#699db3" opacity=".85"/>`+(title.startsWith('KATRINA')?'<path d="M245 285V220H255V245" stroke="#c9d3cb" stroke-width="9" fill="none"/>':'')+'<path d="M325 250V207h45v43M318 207l30-24 30 24" fill="#cebda9" stroke="#e7d9c9" stroke-width="3"/>'+ar(50,145,225,145)+dot(50+175*t,145,6)+tx(25,90,'Wind drives water towards the coast',13)+tx(25,320,'Not a wave-height or Saffir–Simpson category scale',11);return wrap(b,c);}
